export const localizeHabitName = (name: string | undefined | null, lang: SupportedLanguage): string => {
  if (!name) return '';
  const trimmed = name.trim();
  const clean = trimmed.toLowerCase();
  
  // 1. Exact match in alias dictionary
  const key = HABIT_NAME_ALIASES[clean];
  if (key) {
    return translate(lang, key, name);
  }

  // 2. Stripped emojis or numbers
  const stripped = clean.replace(/[\u{1F300}-\u{1F9FF}]|[\u{2600}-\u{26FF}]|[\u{2700}-\u{27BF}]/gu, '').trim();
  if (stripped && HABIT_NAME_ALIASES[stripped]) {
    return translate(lang, HABIT_NAME_ALIASES[stripped], name);
  }

  // 3. Keyword / Substring Matching for common habits
  if (/\b(?:3l\s*water|3\s*liters?|3\s*litres?)\b/i.test(clean)) return translate(lang, 'habit.drink_3l_water', name);
  if (/\b(?:water|hydration|hydrate|drinking\s*water)\b/i.test(clean)) return translate(lang, 'habit.drink_water', name);
  if (/\b(?:exercise|workout|gym|fitness|bodybuilding)\b/i.test(clean)) return translate(lang, 'habit.exercise', name);
  if (/\b(?:read|reading|book|pages)\b/i.test(clean)) return translate(lang, 'habit.read_pages', name);
  if (/\b(?:meditate|meditation|meditating|mindful|mindfulness|breathwork)\b/i.test(clean)) return translate(lang, 'habit.meditate', name);
  if (/\b(?:study|studying|learn|learning)\b/i.test(clean)) return translate(lang, 'habit.study', name);
  if (/\b(?:journal|journaling|diary)\b/i.test(clean)) return translate(lang, 'habit.evening_journal', name);
  if (/\b(?:sleep|sleeping|bedtime)\b/i.test(clean)) return translate(lang, 'habit.sleep_early', name);
  if (/\b(?:walk|walking|steps)\b/i.test(clean)) return translate(lang, 'habit.walk_steps', name);
  if (/\b(?:morning\s*run|5km\s*run|5k\s*run|jog|jogging|morning\s*jog|run|running)\b/i.test(clean)) return translate(lang, 'habit.morning_run', name);
  if (/\b(?:cold\s*shower|shower)\b/i.test(clean)) return translate(lang, 'habit.cold_shower', name);
  if (/\b(?:plan\s*tomorrow|daily\s*plan|planning|plan)\b/i.test(clean)) return translate(lang, 'habit.plan_tomorrow', name);
  if (/\b(?:deep\s*work|focused?\s*work|focus\s*time|focus)\b/i.test(clean)) return translate(lang, 'habit.deep_work', name);
  if (/\b(?:stretch|stretching|yoga|mobility)\b/i.test(clean)) return translate(lang, 'habit.stretch_mobility', name);
  if (/\b(?:healthy\s*eating|diet|healthy\s*food|clean\s*eating)\b/i.test(clean)) return translate(lang, 'habit.healthy_eating', name);
  if (/\b(?:coding|code|code\s*practice|programming)\b/i.test(clean)) return translate(lang, 'habit.coding_practice', name);
  if (/\b(?:leetcode)\b/i.test(clean)) return translate(lang, 'habit.leetcode_daily', name);
  if (/\b(?:strength|strength\s*workout|strength\s*training|weight\s*training|weights?|lifting)\b/i.test(clean)) return translate(lang, 'habit.strength_workout', name);

  return name;
};

export const localizeHabitDescription = (desc: string | undefined | null, lang: SupportedLanguage): string => {
  if (!desc) return '';
  const trimmed = desc.trim();
  const clean = trimmed.toLowerCase();

  // 1. Exact match in alias dictionary
  const key = HABIT_DESC_ALIASES[clean];
  if (key) {
    return translate(lang, key, desc);
  }

  // 2. Check for dynamic "Shared routine with {name}" or "Shared with {name}" across all languages
  const sharedRoutinePatterns = [
    /^(?:shared routine with|shared with)\s+([^🤝\n\r]+?)(?:\s*🤝)?$/i,
    /^(.+?)\s*(?:के साथ साझा दिनचर्या|के साथ साझा)(?:\s*🤝)?$/u,
    /^(.+?)\s*(?:తో భాగస్వామ్య దినచర్య|తో భాగస్వామ్యం చేయబడింది|తో భాగస్వామ్యం)(?:\s*🤝)?$/u,
    /^(.+?)\s*(?:உடன் பகிரப்பட்ட வழக்கம்|உடன் பகிரப்பட்டது)(?:\s*🤝)?$/u,
    /^(.+?)\s*(?:ಅವರೊಂದಿಗೆ ಹಂಚಿಕೊಂಡ ದಿನಚರಿ|ಅವರೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಲಾಗಿದೆ)(?:\s*🤝)?$/u,
    /^(.+?)\s*(?:ഒപ്പമുള്ള പങ്കിട്ട ദിനചര്യ|പങ്കിട്ടത്)(?:\s*🤝)?$/u,
    /^(.+?)\s*(?:-এর সাথে শেয়ার করা রুটিন|-এর সাথে শেয়ার করা)(?:\s*🤝)?$/u,
    /^(.+?)\s*(?:सोबत सामायिक दिनचर्या|सोबत सामायिक)(?:\s*🤝)?$/u,
    /^(.+?)\s*(?:સાથે શેર કરેલ દિનચર્યા|સાથે શેર કરેલ)(?:\s*🤝)?$/u,
  ];

  for (const pat of sharedRoutinePatterns) {
    const match = trimmed.match(pat);
    if (match && match[1]) {
      const buddyName = match[1].trim();
      if (buddyName) {
        return translate(lang, 'habit_desc.shared_routine_with', `Shared routine with ${buddyName} 🤝`, { name: buddyName });
      }
    }
  }

  // 3. Stripped emojis match
  const stripped = clean.replace(/[\u{1F300}-\u{1F9FF}]|[\u{2600}-\u{26FF}]|[\u{2700}-\u{27BF}]/gu, '').trim();
  if (stripped && HABIT_DESC_ALIASES[stripped]) {
    return translate(lang, HABIT_DESC_ALIASES[stripped], desc);
  }

  // 4. Keyword / Substring Matching for common habit descriptions
  if (/\b(?:hydration|daily hydration|drink 3l|drink water)\b/i.test(clean)) return translate(lang, 'habit_desc.daily_hydration_goal', desc);
  if (/\b(?:workout|physical activity)\b/i.test(clean)) return translate(lang, 'habit_desc.exercise', desc);
  if (/\b(?:book reading|read book|commute)\b/i.test(clean)) return translate(lang, 'habit_desc.read_pages', desc);
  if (/\b(?:mindfulness|calm breathing|breathwork)\b/i.test(clean)) return translate(lang, 'habit_desc.deep_meditation', desc);
  if (/\b(?:cardio|endurance run|morning cardio)\b/i.test(clean)) return translate(lang, 'habit_desc.morning_run', desc);
  if (/\b(?:algorithmic problem|solve 1|leetcode)\b/i.test(clean)) return translate(lang, 'habit_desc.leetcode_daily', desc);
  if (/\b(?:resistance|core training)\b/i.test(clean)) return translate(lang, 'habit_desc.strength_workout', desc);

  return desc;
};
